package vn.edu.school.schedule.notification.api;
import java.util.List;import java.util.UUID;import org.slf4j.MDC;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import vn.edu.school.schedule.notification.NotificationService;import vn.edu.school.schedule.shared.api.ApiResponse;import vn.edu.school.schedule.shared.security.AuthenticatedUser;import vn.edu.school.schedule.shared.web.CorrelationIdFilter;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController{private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}@GetMapping ApiResponse<List<NotificationResponse>> list(@RequestParam(required=false)Boolean read,@AuthenticationPrincipal AuthenticatedUser actor){return ApiResponse.success(service.list(actor,read),cid());}@GetMapping("/unread-count")ApiResponse<UnreadCount> unread(@AuthenticationPrincipal AuthenticatedUser actor){return ApiResponse.success(service.unread(actor),cid());}@PatchMapping("/{id}/read")ApiResponse<NotificationResponse> read(@PathVariable UUID id,@AuthenticationPrincipal AuthenticatedUser actor){return ApiResponse.success(service.markRead(id,actor),cid());}@PatchMapping("/read-all")ApiResponse<MarkAllResult> all(@AuthenticationPrincipal AuthenticatedUser actor){return ApiResponse.success(service.markAll(actor),cid());}private String cid(){String v=MDC.get(CorrelationIdFilter.MDC_KEY);return v==null?"unavailable":v;}}
